package com.example

import com.example.ExamQuestionHelper.QSpec

object CivicsLiveExamGlobalBank2 {
    private const val T = "විදේශ ප්‍රතිපත්තිය, ජාත්‍යන්තර සංවිධාන හා මානුෂීය නීතිය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පළමුවන ලෝක යුද්ධයෙන් පසුව ලෝක සාමය රැකීම සඳහා 1920 දී පිහිටුවන ලද ජාත්‍යන්තර සංවිධානය කුමක්ද?", "ජාතීන්ගේ සංගමය", "එක්සත් ජාතීන්ගේ සංවිධානය", "පොදුරාජ්‍ය මණ්ඩලය", "නොබැඳි ජාතීන්ගේ සංවිධානය", "ජාතීන්ගේ සංගමය 1920 ජනවාරි 10 දින ආරම්භ විය."),
        q("ජාතීන්ගේ සංගමයේ මූලස්ථානය පිහිටා තිබූ නගරය කුමක්ද?", "ජිනීවා", "නිව්යෝක්", "හේග්", "වියානා", "ස්විට්සර්ලන්තයේ ජිනීවා නුවර ජාතීන්ගේ සංගමයේ මූලස්ථානය විය."),
        q("ජාතීන්ගේ සංගමය අසාර්ථක වීමට ප්‍රධාන වශයෙන් බලපෑ ඓතිහාසික සිදුවීම කුමක්ද?", "දෙවන ලෝක යුද්ධය ආරම්භ වීම", "සීතල යුද්ධය අවසන් වීම", "බැංඩුං සමුළුව පැවැත්වීම", "බර්ලින් තාප්පය බිඳ වැටීම", "දෙවන ලෝක යුද්ධය වැළැක්වීමට නොහැකි වීමෙන් ජාතීන්ගේ සංගමය බිඳ වැටුණි."),
        q("එක්සත් ජාතීන්ගේ සංවිධානය නිල වශයෙන් ආරම්භ කරන ලද දිනය කවදාද?", "1945 ඔක්තෝබර් 24", "1948 දෙසැම්බර් 10", "1945 අප්‍රේල් 25", "1955 දෙසැම්බර් 14", "1945 ඔක්තෝබර් 24 එක්සත් ජාතීන්ගේ දිනය ලෙස සැමරේ."),
        q("එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය 1945 ජූනි 26 දින අත්සන් කරන ලද සමුළුව පැවති නගරය කුමක්ද?", "සැන් ෆ්‍රැන්සිස්කෝ", "යාල්ටා", "ටෙහෙරාන්", "ඩම්බාටන් ඕක්ස්", "රටවල් 50ක නියෝජිතයෝ සැන් ෆ්‍රැන්සිස්කෝ හිදී ප්‍රඥප්තියට අත්සන් තැබූහ."),
        q("එක්සත් ජාතීන්ගේ සංවිධානයේ මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "නිව්යෝක්", "වොෂින්ටන්", "ජිනීවා", "පැරිස්", "ඇමරිකා එක්සත් ජනපදයේ නිව්යෝක් නුවර එක්සත් ජාතීන්ගේ මූලස්ථානය පිහිටා ඇත."),
        q("එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය යටතේ පිහිටුවා ඇති ප්‍රධාන ආයතන සංඛ්‍යාව කීයද?", "හයකි", "පහකි", "හතකි", "අටකි", "මහා මණ්ඩලය, ආරක්ෂක මණ්ඩලය, ආර්ථික සමාජ මණ්ඩලය, භාරකාර මණ්ඩලය, අධිකරණය හා මහලේකම් කාර්යාලය එම ආයතන 6 වේ."),
        q("එක්සත් ජාතීන්ගේ මහා මණ්ඩලයේ සෑම සාමාජික රාජ්‍යයකටම හිමි ඡන්ද බලය කුමක්ද?", "එක් රටකට එක් ඡන්දයකි", "ජනගහනය අනුව ඡන්ද හිමි වේ", "ආර්ථික බලය අනුව ඡන්ද ලැබේ", "ස්ථිර සාමාජිකයන්ට පමණක් ඡන්ද හිමි වේ", "සාමාජික රාජ්‍යයන්හි ස්වෛරී සමානාත්මතාව අනුව එක් රටකට එක් ඡන්දයක් හිමි වේ."),
        q("එක්සත් ජාතීන්ගේ මහා මණ්ඩලය වාර්ෂිකව නිත්‍ය සැසිවාරය සඳහා රැස්වන්නේ කුමන මාසයේද?", "සැප්තැම්බර්", "ජනවාරි", "මැයි", "දෙසැම්බර්", "සෑම වසරකම සැප්තැම්බර් මාසයේදී නිත්‍ය සැසිවාරය ආරම්භ වේ."),
        q("එක්සත් ජාතීන්ගේ ආරක්ෂක මණ්ඩලයේ සම්පූර්ණ සාමාජික සංඛ්‍යාව කීයද?", "පහළොවකි", "දහයකි", "පනස් හතරකි", "විසි එකකි", "ආරක්ෂක මණ්ඩලය ස්ථිර සාමාජිකයන් 5කින් සහ ස්ථිර නොවන සාමාජිකයන් 10කින් සමන්විතය."),
        q("එක්සත් ජාතීන්ගේ ආරක්ෂක මණ්ඩලයේ නිෂේධ බලය හිමි ස්ථිර සාමාජික රටවල් පහ කුමක්ද?", "ඇමරිකාව, බ්‍රිතාන්‍යය, ප්‍රංශය, රුසියාව, චීනය", "ඇමරිකාව, ජර්මනිය, ජපානය, ඉන්දියාව, බ්‍රසීලය", "බ්‍රිතාන්‍යය, ඉතාලිය, ස්පාඤ්ඤය, රුසියාව, චීනය", "ඇමරිකාව, කැනඩාව, ප්‍රංශය, චීනය, ඕස්ට්‍රේලියාව", "මෙම රටවල් 5 දෙවන ලෝක යුද්ධයෙන් පසු ස්ථිර සාමාජිකත්වය ලැබීය."),
        q("ආරක්ෂක මණ්ඩලයේ ස්ථිර නොවන සාමාජික රටවල් 10 තෝරා ගනු ලබන්නේ කුමන කාල සීමාවක් සඳහාද?", "වසර දෙකකට", "වසර පහකට", "වසර තුනකට", "වසර නවයකට", "මහා මණ්ඩලය විසින් ස්ථිර නොවන සාමාජිකයන් වසර 2ක් සඳහා තෝරා ගනු ලැබේ."),
        q("එක්සත් ජාතීන්ගේ ආරක්ෂක මණ්ඩලයේ ස්ථිර සාමාජිකයෙකුගේ 'නිෂේධ බලය' යනු කුමක්ද?", "තනි විරුද්ධ ඡන්දයකින් යෝජනාවක් ප්‍රතික්ෂේප කිරීමේ බලය", "මහලේකම්වරයා ඒකපාර්ශ්විකව පත් කිරීමේ බලය", "මහා මණ්ඩලය විසුරුවා හැරීමේ බලය", "සාමාජික රටක භූමිය අත්පත් කර ගැනීමේ බලය", "ඕනෑම ස්ථිර සාමාජිකයෙකු විරුද්ධ වුවහොත් ආරක්ෂක මණ්ඩල යෝජනාවක් සම්මත නොවේ."),
        q("ජාත්‍යන්තර සාමය හා ආරක්ෂාව පවත්වා ගැනීම සඳහා බැඳීම් සහිත තීරණ ගැනීමේ මූලික වගකීම ඇති එක්සත් ජාතීන්ගේ ආයතනය කුමක්ද?", "ආරක්ෂක මණ්ඩලය", "භාරකාර මණ්ඩලය", "ආර්ථික හා සමාජ මණ්ඩලය", "ජාත්‍යන්තර අධිකරණය", "සාමය ආරක්ෂා කිරීම සඳහා සම්බාධක හෝ හමුදා ක්‍රියාමාර්ග ගැනීමේ බලය ආරක්ෂක මණ්ඩලයට ඇත."),
        q("ජාත්‍යන්තර අධිකරණය පිහිටා ඇති නගරය සහ රට කුමක්ද?", "නෙදර්ලන්තයේ හේග්", "ස්විට්සර්ලන්තයේ ජිනීවා", "ප්‍රංශයේ පැරිස්", "ඔස්ට්‍රියාවේ වියානා", "එක්සත් ජාතීන්ගේ මූලස්ථානයෙන් පිටත පිහිටි එකම ප්‍රධාන ආයතනය හේග් හි ජාත්‍යන්තර අධිකරණයයි."),
        q("ජාත්‍යන්තර අධිකරණයට විනිසුරුවරුන් කී දෙනෙකු කොපමණ ධුර කාලයක් සඳහා තෝරා ගනු ලැබේද?", "විනිසුරුවරුන් 15 දෙනෙකු වසර 9කට", "විනිසුරුවරුන් 9 දෙනෙකු වසර 5කට", "විනිසුරුවරුන් 11 දෙනෙකු වසර 6කට", "විනිසුරුවරුන් 15 දෙනෙකු වසර 4කට", "මහා මණ්ඩලය හා ආරක්ෂක මණ්ඩලය විසින් විනිසුරුවරුන් 15ක් වසර 9කට පත් කෙරේ."),
        q("එක්සත් ජාතීන්ගේ සංවිධානයේ ප්‍රධාන පරිපාලන නිලධාරියා කවුද?", "මහලේකම්වරයා", "මහා මණ්ඩල සභාපති", "ආරක්ෂක මණ්ඩල සභාපති", "අධිකරණ අගවිනිසුරු", "මහලේකම් කාර්යාලයේ ප්‍රධානියා වන්නේ මහලේකම්වරයාය."),
        q("එක්සත් ජාතීන්ගේ මහලේකම්වරයා පත් කරනු ලබන්නේ කෙසේද?", "ආරක්ෂක මණ්ඩලයේ නිර්දේශය මත මහා මණ්ඩලය විසින්", "සාමාජික රටවල ජනමත විචාරණයකින්", "ජාත්‍යන්තර අධිකරණයේ විනිසුරුවරුන් විසින්", "ආර්ථික හා සමාජ මණ්ඩලයේ ඡන්දයෙන්", "ආරක්ෂක මණ්ඩලයේ නිර්දේශයෙන් පසු මහා මණ්ඩලය වසර 5ක් සඳහා පත් කරයි."),
        q("එක්සත් ජාතීන්ගේ ආර්ථික හා සමාජ මණ්ඩලයේ (ECOSOC) සාමාජික රටවල් සංඛ්‍යාව කීයද?", "පනස් හතරකි", "පහළොවකි", "තිස් හයකි", "හතළිස් පහකි", "වසර 3ක කාලයක් සඳහා මහා මණ්ඩලයෙන් රටවල් 54ක් තෝරා ගැනේ."),
        q("1994 දී පලාවු රාජ්‍යය නිදහස ලැබීමෙන් පසු සිය මෙහෙයුම් අත්හිටුවන ලද එක්සත් ජාතීන්ගේ ප්‍රධාන ආයතනය කුමක්ද?", "භාරකාර මණ්ඩලය", "ආරක්ෂක මණ්ඩලය", "ආර්ථික හා සමාජ මණ්ඩලය", "මහලේකම් කාර්යාලය", "භාරකාර ප්‍රදේශ සියල්ල නිදහස ලැබීමත් සමඟ භාරකාර මණ්ඩලයේ කටයුතු අත්හිටුවන ලදී."),
        q("එක්සත් ජාතීන්ගේ ප්‍රථම මහලේකම්වරයා ලෙස සේවය කළේ කවුද?", "ට්‍රිග්වේ ලී", "ඩැග් හැමර්ෂෝල්ඩ්", "ඌ තාන්ට්", "කොෆි අන්නන්", "නෝර්වේ ජාතික ට්‍රිග්වේ ලී 1946–1952 කාලයේ පළමු මහලේකම්වරයා විය."),
        q("එක්සත් ජාතීන්ගේ ආසියානු ජාතික ප්‍රථම මහලේකම්වරයා කවුද?", "බුරුමයේ ඌ තාන්ට්", "කොරියාවේ බෑන් කී මූන්", "පේරු හි ජේවියර් පෙරෙස්", "ඊජිප්තුවේ බුත්‍රෝස් ගාලි", "මියන්මාරයේ (බුරුමයේ) ඌ තාන්ට් ආසියාවෙන් පත් වූ පළමු මහලේකම්වරයාය."),
        q("එක්සත් ජාතීන්ගේ සංවිධානයේ වත්මන් (නවවන) මහලේකම්වරයා කවුද?", "ඇන්ටෝනියෝ ගුටේරස්", "බෑන් කී මූන්", "කොෆි අන්නන්", "වොල්කර් ටර්ක්", "පෘතුගාලයේ හිටපු අගමැති ඇන්ටෝනියෝ ගුටේරස් 2017 සිට මහලේකම් ධුරය දරයි."),
        q("එක්සත් ජාතීන්ගේ සංවිධානයේ නිල භාෂා සංඛ්‍යාව කීයද?", "හයකි", "හතරකි", "පහකි", "අටකි", "ඉංග්‍රීසි, ප්‍රංශ, ස්පාඤ්ඤ, රුසියානු, චීන සහ අරාබි යන භාෂා 6 නිල භාෂා වේ."),
        q("අධ්‍යාපනය, විද්‍යාව සහ සංස්කෘතිය ප්‍රවර්ධනය කරන එක්සත් ජාතීන්ගේ විශේෂිත ආයතනය කුමක්ද?", "යුනෙස්කෝ (UNESCO)", "යුනිසෙෆ් (UNICEF)", "ලෝක සෞඛ්‍ය සංවිධානය (WHO)", "ආහාර හා කෘෂිකර්ම සංවිධානය (FAO)", "යුනෙස්කෝ ආයතනයේ මූලස්ථානය ප්‍රංශයේ පැරිස් නුවර පිහිටා ඇත."),
        q("ලොව පුරා දරුවන්ගේ අයිතිවාසිකම්, සෞඛ්‍යය හා පෝෂණය වෙනුවෙන් ක්‍රියා කරන එක්සත් ජාතීන්ගේ අරමුදල කුමක්ද?", "යුනිසෙෆ් (UNICEF)", "යුනෙස්කෝ (UNESCO)", "ජාත්‍යන්තර කම්කරු සංවිධානය (ILO)", "ලෝක වෙළෙඳ සංවිධානය (WTO)", "UNICEF මූලස්ථානය නිව්යෝක් නුවර පිහිටා ඇත."),
        q("ලෝක සෞඛ්‍ය සංවිධානයේ (WHO) මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "ජිනීවා", "රෝමය", "පැරිස්", "නිව්යෝක්", "සෑම වසරකම අප්‍රේල් 7 දින ලෝක සෞඛ්‍ය දිනය ලෙස WHO සමරයි."),
        q("ලෝක ආහාර සුරක්ෂිතතාව හා කෘෂිකාර්මික සංවර්ධනය සඳහා පිහිටුවා ඇති FAO ආයතනයේ මූලස්ථානය කොහේද?", "රෝමය", "ජිනීවා", "ලන්ඩන්", "වියානා", "ඉතාලියේ රෝම නුවර ආහාර හා කෘෂිකර්ම සංවිධානයේ මූලස්ථානය පිහිටා ඇත."),
        q("සේවක අයිතිවාසිකම් හා ජාත්‍යන්තර කම්කරු ප්‍රමිතීන් සකස් කරන ජාත්‍යන්තර කම්කරු සංවිධානය (ILO) පිහිටුවන ලද්දේ කවදාද?", "1919 දී", "1945 දී", "1948 දී", "1965 දී", "1919 වර්සේල්ස් ගිවිසුමෙන් ILO ආරම්භ වී පසුව UN විශේෂිත ආයතනයක් විය."),
        q("සරණාගතයින්ගේ ආරක්ෂාව හා සුබසාධනය වෙනුවෙන් කටයුතු කරන එක්සත් ජාතීන්ගේ ආයතනය කුමක්ද?", "UNHCR", "UNDP", "UNEP", "UNFPA", "UNHCR යනු එක්සත් ජාතීන්ගේ සරණාගතයින් පිළිබඳ මහ කොමසාරිස් කාර්යාලයයි."),
        q("රටවල ගෙවුම් ශේෂ හා මූල්‍ය ස්ථාවරත්වය සඳහා කෙටි කාලීන ණය සපයන ජාත්‍යන්තර ආයතනය කුමක්ද?", "ජාත්‍යන්තර මූල්‍ය අරමුදල (IMF)", "ලෝක ආහාර වැඩසටහන (WFP)", "ජාත්‍යන්තර කම්කරු සංවිධානය (ILO)", "එක්සත් ජාතීන්ගේ පරිසර වැඩසටහන (UNEP)", "1944 බ්‍රෙටන් වුඩ්ස් සමුළුවෙන් IMF සහ ලෝක බැංකුව පිහිටුවීමට තීරණය විය."),
        q("දිළිඳුකම පිටුදැකීම හා දිගුකාලීන සංවර්ධන ව්‍යාපෘති සඳහා රටවලට ණය හා ආධාර සපයන ආයතනය කුමක්ද?", "ලෝක බැංකුව (IBRD)", "ජාත්‍යන්තර පරමාණුක බලශක්ති ආයතනය", "ලෝක කාලගුණ සංවිධානය", "ජාත්‍යන්තර සිවිල් ගුවන් සේවා සංවිධානය", "ලෝක බැංකුවේ මූලස්ථානය වොෂින්ටන් නුවර පිහිටා ඇත."),
        q("ජාත්‍යන්තර වෙළෙඳ නීති නියාමනය කිරීම සඳහා 1995 දී GATT වෙනුවට පිහිටුවන ලද සංවිධානය කුමක්ද?", "ලෝක වෙළෙඳ සංවිධානය (WTO)", "ආසියානු සංවර්ධන බැංකුව (ADB)", "යුරෝපා සංගමය (EU)", "දකුණු ආසියානු නිදහස් වෙළෙඳ ගිවිසුම", "1995 ජනවාරි 1 දින ජිනීවා මූලස්ථානය කරගනිමින් WTO පිහිටුවන ලදී."),
        q("එක්සත් ජාතීන්ගේ පරිසර වැඩසටහනේ (UNEP) මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "නයිරෝබි", "රෝමය", "බැංකොක්", "ටෝකියෝ", "කෙන්යාවේ නයිරෝබි නුවර UNEP මූලස්ථානය පිහිටා ඇත."),
        q("දකුණු ආසියානු කලාපීය සහයෝගීතා සංවිධානය (SAARC) ආරම්භ කරන ලද්දේ කවදාද සහ කොහේද?", "1985 දෙසැම්බර් 8 ඩකා හිදී", "1980 මැයි 2 කොළඹ හිදී", "1990 ජනවාරි 1 නවදිල්ලියේදී", "1976 අගෝස්තු 16 කත්මණ්ඩු හිදී", "බංග්ලාදේශයේ ඩකා නුවරදී දකුණු ආසියාතික රටවල් 7ක නායකයෝ සාර්ක් සංවිධානය පිහිටුවූහ."),
        q("සාර්ක් (SAARC) සංවිධානය පිහිටුවීම සඳහා මූලික යෝජනාව ඉදිරිපත් කළ බංග්ලාදේශ ජනාධිපතිවරයා කවුද?", "සියාවුර් රහ්මාන්", "ෂෙයික් මුජිබුර් රහ්මාන්", "හුසේන් මොහොමඩ් අර්ෂාඩ්", "ඛලීඩා සියා", "1980 දී බංග්ලාදේශ ජනාධිපති සියාවුර් රහ්මාන් කලාපීය සහයෝගීතා යෝජනාව ගෙන ආවේය."),
        q("සාර්ක් සංවිධානයේ මහලේකම් කාර්යාලය පිහිටා ඇති නගරය කුමක්ද?", "කත්මණ්ඩු", "ඩකා", "නවදිල්ලිය", "ඉස්ලාමාබාද්", "නේපාලයේ කත්මණ්ඩු නුවර 1987 දී සාර්ක් මහලේකම් කාර්යාලය ස්ථාපිත කෙරිණි."),
        q("2007 වසරේදී අටවන සාමාජික රාජ්‍යය ලෙස සාර්ක් සංවිධානයට එක් වූ රට කුමක්ද?", "ඇෆ්ගනිස්ථානය", "මියන්මාරය", "මාලදිවයින", "භූතානය", "2007 නවදිල්ලි සමුළුවේදී ඇෆ්ගනිස්ථානය සාර්ක් සාමාජිකත්වය ලබා ගත්තේය."),
        q("පහත සඳහන් රටවල් අතරින් සාර්ක් සංවිධානයේ සාමාජික රටක් නොවන්නේ කුමක්ද?", "මියන්මාරය", "භූතානය", "මාලදිවයින", "නේපාලය", "ශ්‍රී ලංකාව, ඉන්දියාව, පාකිස්තානය, බංග්ලාදේශය, නේපාලය, භූතානය, මාලදිවයින සහ ඇෆ්ගනිස්ථානය සාර්ක් රටවල් 8 වේ."),
        q("සාර්ක් කලාපයේ රටවල් අතර වෙළෙඳ තීරුබදු අඩු කරමින් 2006 දී ක්‍රියාත්මක වූ නිදහස් වෙළෙඳ ගිවිසුම කුමක්ද?", "සැෆ්ටා (SAFTA)", "බිම්ස්ටෙක් (BIMSTEC)", "ආසියාන් (ASEAN)", "නැෆ්ටා (NAFTA)", "South Asian Free Trade Area (SAFTA) යනු දකුණු ආසියානු නිදහස් වෙළෙඳ ගිවිසුමයි."),
        q("ශ්‍රී ලංකාව සාර්ක් සමුළු සඳහා සත්කාරකත්වය සැපයූ වර්ෂ තුන කුමක්ද?", "1991, 1998 සහ 2008", "1985, 1990 සහ 2000", "1988, 1995 සහ 2012", "1993, 2002 සහ 2014", "1991 (6වන), 1998 (10වන) සහ 2008 (15වන) සාර්ක් සමුළු කොළඹදී පැවැත්විණි."),
        q("දකුණු ආසියාව හා අග්නිදිග ආසියාව යා කරන බෙංගාල බොක්ක ආශ්‍රිත කලාපීය ආර්ථික හා තාක්ෂණික සහයෝගීතා සංවිධානය කුමක්ද?", "බිම්ස්ටෙක් (BIMSTEC)", "නේටෝ (NATO)", "ඕපෙක් (OPEC)", "යුරෝපා සංගමය (EU)", "බංග්ලාදේශය, ඉන්දියාව, මියන්මාරය, ශ්‍රී ලංකාව, තායිලන්තය, නේපාලය හා භූතානය BIMSTEC සාමාජිකයෝ වෙති."),
        q("1967 බැංකොක් ප්‍රකාශනයෙන් පිහිටුවන ලද අග්නිදිග ආසියානු ජාතීන්ගේ සංගමය කුමක්ද?", "ආසියාන් (ASEAN)", "සාර්ක් (SAARC)", "අයෝරා (IORA)", "බ්‍රික්ස් (BRICS)", "තායිලන්තය, මැලේසියාව, සිංගප්පූරුව, ඉන්දුනීසියාව, පිලිපීනය ඇතුළු අග්නිදිග ආසියාතික රටවල් ASEAN හි සාමාජිකයෝය."),
        q("ඉන්දියානු සාගරය ආශ්‍රිත රටවල ආර්ථික හා සමුද්‍රීය සහයෝගීතාව සඳහා පිහිටුවා ඇති සංවිධානය කුමක්ද?", "ඉන්දියන් සාගර වටද්දර සංගමය (IORA)", "පොදුරාජ්‍ය මණ්ඩලය", "අප්‍රිකානු සංගමය", "ලතින් ඇමරිකානු සංගමය", "ශ්‍රී ලංකාව IORA හි ආරම්භක සාමාජික රාජ්‍යයකි."),
        q("බ්‍රිතාන්‍ය අධිරාජ්‍යයෙන් නිදහස ලැබූ රටවල් බහුතරයකින් සැදුම්ලත් ජාත්‍යන්තර සංවිධානය කුමක්ද?", "පොදුරාජ්‍ය මණ්ඩලය", "ආරක්ෂක මණ්ඩලය", "යුරෝපා සංගමය", "අරාබි ලීගය", "1949 ලන්ඩන් ප්‍රකාශනයෙන් නූතන පොදුරාජ්‍ය මණ්ඩලය ස්ථාපිත විය."),
        q("2013 වසරේදී පොදුරාජ්‍ය මණ්ඩලයීය රාජ්‍ය නායක සමුළුව (CHOGM) පැවැත්වූයේ කුමන නගරයේද?", "කොළඹ", "ලන්ඩන්", "සිංගප්පූරුව", "පර්ත්", "2013 නොවැම්බර් මාසයේදී CHOGM සමුළුව ශ්‍රී ලංකාවේ කොළඹදී පැවැත්විණි."),
        q("මාස්ට්‍රිච් ගිවිසුම යටතේ 1993 දී වඩාත් ශක්තිමත් ආර්ථික හා දේශපාලන සංගමයක් බවට පත් වූ කලාපීය සංවිධානය කුමක්ද?", "යුරෝපා සංගමය", "උතුරු අත්ලාන්තික් ගිවිසුම් සංවිධානය", "සාර්ක් සංවිධානය", "නොබැඳි ව්‍යාපාරය", "යුරෝපා සංගමයේ මූලස්ථානය බෙල්ජියමේ බ්‍රසල්ස් හි පිහිටා ඇත."),
        q("ජාත්‍යන්තර මානුෂීය නීතිය (IHL) ප්‍රධාන වශයෙන් අදාළ වන්නේ කුමන අවස්ථාවන්හිදීද?", "සන්නද්ධ ගැටුම් හා යුදමය අවස්ථාවන්හිදී", "සාමකාමී කාලවල පළාත් පාලන ඡන්දවලදී", "අන්තර්ජාතික වෙළෙඳ බදු සාකච්ඡාවලදී", "කලාපීය ක්‍රීඩා තරගාවලි පැවැත්වීමේදී", "යුද්ධයකදී සිවිල් වැසියන් හා සටන් නොකරන පුද්ගලයන් ආරක්ෂා කිරීම IHL හි අරමුණයි."),
        q("රතු කුරුස ව්‍යාපාරය ආරම්භ කිරීමට මූලික වූ ස්විට්සර්ලන්ත ජාතික මානව හිතවාදියා කවුද?", "හෙන්රි ඩුනාන්ට්", "හියුගෝ ග්‍රෝෂියස්", "රෆායෙල් ලෙම්කින්", "ඇල්බට් ෂ්වයිට්සර්", "1859 සොල්ෆෙරිනෝ සටනේ බිහිසුණු බව දුටු හෙන්රි ඩුනාන්ට් 1863 දී ICRC ආරම්භ කළේය."),
        q("හෙන්රි ඩුනාන්ට් 1863 දී ජාත්‍යන්තර රතු කුරුස කමිටුව (ICRC) ආරම්භ කිරීමට පෙර රචනා කළ කෘතිය කුමක්ද?", "සොල්ෆෙරිනෝ මතක සටහන්", "ජාතීන්ගේ නීතිය", "සදාකාලික සාමය", "සමාජ ගිවිසුම", "A Memory of Solferino කෘතිය මානුෂීය සහන සේවා බිහිවීමට පදනම දැමීය."),
        q("නූතන ජාත්‍යන්තර මානුෂීය නීතියේ ප්‍රධානතම ලේඛන හතර වන ජිනීවා සම්මුති අත්සන් කරන ලද්දේ කුමන වර්ෂයේදීද?", "1949 දී", "1919 දී", "1955 දී", "1998 දී", "1949 අගෝස්තු 12 දින ජිනීවා සම්මුති හතර සම්මත කර ගන්නා ලදී."),
        q("1949 පළමු ජිනීවා සම්මුතියෙන් ආරක්ෂාව සැලසෙන්නේ කවුරුන්ටද?", "ගොඩබිම යුද බිමේදී තුවාල ලැබූ සහ රෝගී සෙබළුන්ට", "මුහුදු යුද්ධයේදී නැව් බිඳුණු සෙබළුන්ට", "සාමාන්‍ය පාසල් සිසුන්ට", "රාජ්‍ය තාන්ත්‍රික තානාපතිවරුන්ට", "පළමු සම්මුතිය ගොඩබිම සන්නද්ධ හමුදාවන්හි තුවාලකරුවන් ආරක්ෂා කරයි."),
        q("1949 දෙවන ජිනීවා සම්මුතියෙන් විශේෂයෙන් ආරක්ෂා කෙරෙනුයේ කවුද?", "මුහුදු යුද්ධයේදී තුවාල ලැබූ, රෝගී හා නැව් බිඳුණු සෙබළුන්", "ගුවන් ගමන් පාලක නිලධාරීන්", "සිවිල් පුවත්පත් වාර්තාකරුවන්", "සිරගත කළ දේශපාලන ක්‍රියාකාරීන්", "දෙවන සම්මුතිය නාවික සන්නද්ධ ගැටුම්වල වින්දිතයන් ආරක්ෂා කරයි."),
        q("1949 තුන්වන ජිනීවා සම්මුතිය අදාළ වන්නේ කුමන පිරිසකට සැලකීම පිළිබඳවද?", "යුද සිරකරුවන්ට", "ආර්ථික සංක්‍රමණිකයන්ට", "සාම සාධක නිරීක්ෂකයන්ට", "විදේශීය සංචාරකයන්ට", "අත්අඩංගුවට ගත් සතුරු සෙබළුන්ට මානුෂීයව සැලකීම තුන්වන සම්මුතියෙන් තහවුරු කෙරේ."),
        q("1949 හතරවන ජිනීවා සම්මුතිය මඟින් ආරක්ෂාව තහවුරු කර ඇත්තේ කවුරුන් සඳහාද?", "යුද ගැටුම් පවතින ප්‍රදේශවල සිවිල් වැසියන්", "ප්‍රහාරක ගුවන් නියමුවන්", "යුද උපකරණ නිෂ්පාදකයින්", "සමුද්‍ර කොල්ලකරුවන්", "සටන් නොකරන සාමාන්‍ය ජනතාවගේ ජීවිත හා දේපළ ආරක්ෂා කිරීම හතරවන සම්මුතියේ අරමුණයි."),
        q("1949 ජිනීවා සම්මුතිවලට අතිරේකව ජාත්‍යන්තර හා අභ්‍යන්තර ගැටුම් ආවරණය කිරීමට අතිරේක සන්ධාන පත්‍ර (Protocols) එක් කළේ කවදාද?", "1977 දී", "1954 දී", "1966 දී", "1989 දී", "1977 අතිරේක ප්‍රොටෝකෝල I සහ II මඟින් ගැටුම්වලදී සිවිල් ආරක්ෂාව පුළුල් කෙරිණි."),
        q("ජාත්‍යන්තර මානුෂීය නීතියේ මූලික මූලධර්මයක් වන 'වෙනස හඳුනා ගැනීමේ මූලධර්මය' (Principle of Distinction) යනු කුමක්ද?", "සටන්කරුවන් හා සිවිල් වැසියන් අතර පැහැදිලි වෙනසක් සිදු කිරීම", "ධනවත් හා දිළිඳු රටවල් වෙන් කර හඳුනා ගැනීම", "දේශීය හා විදේශීය බැංකු වෙන් කිරීම", "ජාතික හා පළාත් මාර්ග වර්ග කිරීම", "ප්‍රහාර එල්ල කළ හැක්කේ හමුදා ඉලක්ක වෙත පමණක් වන අතර සිවිල් ජනතාව ඉලක්ක නොකළ යුතුය."),
        q("යුද්ධයකදී ආයුධ බිම තැබූ හෝ තුවාල ලබා සටන් කළ නොහැකි තත්ත්වයට පත් සෙබළුන් හඳුන්වන පදය කුමක්ද?", "හෝර්ස් ඩි කොම්බැට් (Hors de combat)", "පර්සෝනා නොන් ග්‍රාටා", "ජුස් සෝලි", "ස්ටේටස් ක්වෝ", "සටනින් ඉවත් වූ හෝ යටත් වූ සෙබළුන්ට පහර දීම මානුෂීය නීතියෙන් තහනම්ය."),
        q("ජාත්‍යන්තර මානුෂීය නීතිය යටතේ රෝහල්, ගිලන්රථ හා වෛද්‍ය සේවකයන් ආරක්ෂිත බව දැක්වීමට භාවිත කරන ලාංඡන මොනවාද?", "රතු කුරුස, රතු අඩසඳ හා රතු පළිඟු", "නිල් තාරකාව හා කොළ පත්‍රය", "කහ ත්‍රිකෝණය හා කළු වෘත්තය", "සුදු පරෙවියා හා රන් කඩුව", "මෙම ආරක්ෂිත ලාංඡන සහිත වෛද්‍ය ආයතනවලට පහර දීම යුද අපරාධයකි."),
        q("ජාත්‍යන්තර මානුෂීය නීතිය යටතේ භාවිතය සම්පූර්ණයෙන්ම තහනම් කර ඇති අවි වර්ගයකට නිදසුනක් කුමක්ද?", "රසායනික හා ජීව විද්‍යාත්මක අවි", "සාම්ප්‍රදායික පාබල රයිෆල්", "හමුදා සන්නිවේදන රේඩියෝ", "ආරක්ෂක රේඩාර් පද්ධති", "අනවශ්‍ය වේදනා ගෙන දෙන හා සිවිල් ජනතාව විනාශ කරන රසායනික හා ජීව අවි තහනම්ය."),
        q("ජිනීවා සම්මුතිවලට අනුව සන්නද්ධ හමුදා සඳහා ළමුන් බඳවා ගැනීම සම්පූර්ණයෙන් තහනම් වන අවම වයස් සීමාව කීයද?", "වයස අවුරුදු 18ට අඩු", "වයස අවුරුදු 21ට අඩු", "වයස අවුරුදු 12ට අඩු", "වයස අවුරුදු 16ට අඩු", "ළමා අයිතිවාසිකම් ප්‍රඥප්තියේ විකල්ප ප්‍රොටෝකෝලය අනුව වයස 18ට අඩු අය සටන් සඳහා යෙදවීම තහනම්ය."),
        q("යුද අපරාධ, මනුෂ්‍යත්වයට එරෙහි අපරාධ සහ ජන සංහාර විභාග කිරීම සඳහා 1998 රෝම ව්‍යවස්ථාවෙන් පිහිටුවූ ස්ථිර අධිකරණය කුමක්ද?", "ජාත්‍යන්තර අපරාධ අධිකරණය (ICC)", "ජාත්‍යන්තර කම්කරු විනිශ්චය සභාව", "ලෝක වෙළෙඳ ආරවුල් මණ්ඩලය", "එක්සත් ජාතීන්ගේ භාරකාර මණ්ඩලය", "2002 දී ක්‍රියාත්මක වූ ජාත්‍යන්තර අපරාධ අධිකරණය නෙදර්ලන්තයේ හේග් නුවර පිහිටා ඇත."),
        q("එක්සත් ජාතීන්ගේ සාම සාධක හමුදා සඳහා පොදුවේ භාවිත වන කෙටි නාමය කුමක්ද?", "නිල් හිස්වැසුම් (Blue Helmets)", "කළු තොප්පි", "රතු තරු බළකාය", "කොළ කබා සෙබළුන්", "එක්සත් ජාතීන්ගේ සාම සාධක භටයන් ලා නිල් පැහැති හිස්වැසුම් පැලඳ සිටිති."),
        q("ගැටුම් පවතින රටවල සාමය තහවුරු කිරීම සඳහා එක්සත් ජාතීන්ගේ සාම සාධක මෙහෙයුම්වලට ශ්‍රී ලංකාව දක්වන දායකත්වය කුමක්ද?", "ත්‍රිවිධ හමුදා හා පොලිස් භට පිරිස් යෙදවීම", "න්‍යෂ්ටික අවි සැපයීම", "ආරක්ෂක මණ්ඩලයේ නිෂේධ බලය පාවිච්චි කිරීම", "මහා මණ්ඩලයේ ඡන්ද අවලංගු කිරීම", "හයිටි, ලෙබනනය, මාලි හා දකුණු සුඩානය වැනි රටවල සාම සාධක සේවා සඳහා ශ්‍රී ලංකාව දායක වේ."),
        q("යුද්ධය හෝ හිංසනය නිසා ජාත්‍යන්තර දේශසීමාවක් තරණය කර වෙනත් රටකට පලා ගිය පුද්ගලයෙකු හඳුන්වන්නේ කෙසේද?", "සරණාගතයෙකු (Refugee)", "අභ්‍යන්තරව අවතැන් වූවෙකු (IDP)", "රාජ්‍ය තාන්ත්‍රිකයෙකු", "විදේශ සේවා නියුක්තිකයෙකු", "1951 සරණාගත සම්මුතිය අනුව ජාත්‍යන්තර දේශසීමා පසු කළ අය සරණාගතයෝ වෙති."),
        q("ගැටුම් හෝ ස්වාභාවික විපත් නිසා තම නිවෙස් අතහැර ගිය නමුත් තමන්ගේම රටේ දේශසීමා තුළම රැඳී සිටින පුද්ගලයන් හඳුන්වන්නේ කෙසේද?", "අභ්‍යන්තරව අවතැන් වූ පුද්ගලයන් (IDP)", "සරණාගතයන්", "පුරවැසිභාවය අහිමි වූවන්", "ද්විත්ව පුරවැසියන්", "ජාත්‍යන්තර දේශසීමාවක් පසු නොකර රට තුළම අවතැන් වූවන් IDP ලෙස හැඳින්වේ."),
        q("යුද්ධයේදී සංස්කෘතික උරුමයන්, ආගමික ස්ථාන හා පුරාවස්තු විනාශ කිරීම තහනම් කරන 1954 සම්මුතිය කුමක්ද?", "හේග් සම්මුතිය", "කියෝතෝ සන්ධානය", "මොන්ට්‍රියල් සන්ධානය", "වර්සේල්ස් ගිවිසුම", "1954 හේග් සම්මුතිය සන්නද්ධ ගැටුම්වලදී සංස්කෘතික දේපළ ආරක්ෂා කරයි."),
        q("මත්ද්‍රව්‍ය ජාවාරම හා ජාත්‍යන්තර අපරාධ මර්දනය සඳහා රටවල් අතර පොලිස් සහයෝගීතාව සම්බන්ධීකරණය කරන ආයතනය කුමක්ද?", "ඉන්ටර්පෝල් (INTERPOL)", "යුනිසෙෆ් (UNICEF)", "යුනෙස්කෝ (UNESCO)", "සැෆ්ටා (SAFTA)", "ජාත්‍යන්තර අපරාධ පොලිස් සංවිධානයේ (INTERPOL) මූලස්ථානය ප්‍රංශයේ ලියොන් හි පිහිටා ඇත."),
        q("එක් රටක අපරාධයක් කර වෙනත් රටකට පලා ගිය සැකකරුවෙකු නීත්‍යනුකූලව ආපසු භාර දීමේ ජාත්‍යන්තර ක්‍රියාවලිය කුමක්ද?", "උදර්පණය (Extradition)", "තානාපති මුක්තිය", "රාජ්‍ය පිළිගැනීම", "ප්‍රතික්ෂේප කිරීම", "ද්විපාර්ශ්වික ගිවිසුම් යටතේ සැකකරුවන් භාර දීම උදර්පණය නම් වේ."),
        q("රතු කුරුස හා රතු අඩසඳ සංකේතවලට අමතරව 2005 තුන්වන අතිරේක ප්‍රොටෝකෝලයෙන් හඳුන්වා දුන් ආගමික අනන්‍යතාවයෙන් තොර ආරක්ෂිත ලාංඡනය කුමක්ද?", "රතු පළිඟු (Red Crystal)", "නිල් ත්‍රිකෝණය", "කොළ පැහැති වෘත්තය", "රන් කුරුසය", "සියලු රටවලට හා ආගම්වලට පොදුවේ භාවිත කළ හැකි ආරක්ෂිත ලාංඡනයක් ලෙස රතු පළිඟු සම්මත කෙරිණි."),
        q("එක්සත් ජාතීන්ගේ ළමා අරමුදල හා මානව හිමිකම් නීති යටතේ සරණාගතයෙකු ඔහුගේ ජීවිතයට තර්ජනයක් ඇති රටට බලහත්කාරයෙන් ආපසු නොයැවීමේ මූලධර්මය කුමක්ද?", "ආපසු නොයැවීමේ මූලධර්මය (Non-refoulement)", "ස්වයං නිර්ණ අයිතිය", "තානාපති මුක්තිය", "වැඩි කැමැත්තේ නීතිය", "1951 සරණාගත සම්මුතියේ මූලික ගල වන්නේ Non-refoulement මූලධර්මයයි."),
        q("පුද්ගල අනන්‍යතාව හා ජාතිකත්වයෙන් ඔබ්බට ගොස් සමස්ත මානව සංහතියේ පොදු යහපත වෙනුවෙන් වගකීමෙන් කටයුතු කිරීම කුමක් ලෙස හැඳින්වේද?", "ගෝලීය පුරවැසිභාවය", "පටු ජාතිකවාදය", "හුදෙකලාවාදය", "ඒකාධිපතිවාදය", "දේශගුණික විපර්යාස, සාමය හා මානව හිමිකම් වෙනුවෙන් එක්ව ක්‍රියා කිරීම ගෝලීය පුරවැසිභාවයයි."),
        q("ජාත්‍යන්තර රතු කුරුස හා රතු අඩසඳ ව්‍යාපාරයේ මූලික මූලධර්ම ගණන කීයද?", "හතකි", "තුනකි", "පහකි", "දහයකි", "මානවීයත්වය, අපක්ෂපාතීත්වය, මධ්‍යස්ථභාවය, ස්වාධීනත්වය, ස්වේච්ඡා සේවය, එක්සත්කම හා විශ්වව්‍යාප්ත බව එම මූලධර්ම 7 වේ."),
        q("තම සාමාජික රටවල් අතර යුදමය හෝ දේශපාලන ආරවුල් සාමකාමීව විසඳා ගැනීමට එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය යෝජනා කරන ක්‍රම මොනවාද?", "සාකච්ඡා, මැදිහත්වීම් හා සමථකරණය", "වහාම යුද්ධ ප්‍රකාශ කිරීම", "වෙළෙඳ නැව් ගිල්වා දැමීම", "දේශසීමා බලහත්කාරයෙන් වෙනස් කිරීම", "ප්‍රඥප්තියේ VI වන පරිච්ඡේදය සාමකාමී විසඳුම් දිරිමත් කරයි."),
        q("නව සාමාජික රාජ්‍යයක් එක්සත් ජාතීන්ගේ සංවිධානයට ඇතුළත් කර ගනු ලබන්නේ කෙසේද?", "ආරක්ෂක මණ්ඩලයේ නිර්දේශය මත මහා මණ්ඩලයේ තුනෙන් දෙකක ඡන්දයෙන්", "මහලේකම්වරයාගේ තනි අභිමතය පරිදි", "ජාත්‍යන්තර අධිකරණයේ තීන්දුවකින්", "සාර්ක් සංවිධානයේ අනුමැතියෙන්", "සාමයට ලැදි ස්වෛරී රාජ්‍යයන් ප්‍රඥප්තිය පිළිගැනීමෙන් සාමාජිකත්වය ලබයි."),
        q("දකුණු ආසියාතික රටවල ආහාර හිඟයන් සහ ආපදා අවස්ථාවලදී සහය වීමට සාර්ක් සංවිධානය පිහිටුවා ඇති යාන්ත්‍රණය කුමක්ද?", "සාර්ක් ආහාර බැංකුව", "සාර්ක් ආරක්ෂක හමුදාව", "සාර්ක් න්‍යෂ්ටික අධිකාරිය", "සාර්ක් පොදු මුදල් අධිකාරිය", "හදිසි ආහාර අවශ්‍යතා සපුරාලීම සඳහා සාර්ක් ආහාර බැංකුව ක්‍රියාත්මක වේ."),
        q("එක්සත් ජාතීන්ගේ ප්‍රඥප්තියේ ආරම්භක වදන් වන 'අපි එක්සත් ජාතීන්ගේ ජනතාව' යන්නෙන් අවධාරණය කරන්නේ කුමක්ද?", "මතු පරපුර යුද්ධයේ විපතින් ගලවා මානව අයිතිවාසිකම් හා සමානාත්මතාව සුරැකීම", "ලෝකයේ සියලු රටවල් එක් රජයක් යටතේ පාලනය කිරීම", "වෙළඳ බදු දෙගුණ කිරීම", "සාගර මාර්ග පෞද්ගලීකරණය කිරීම", "යුද්ධය වැළැක්වීම හා මානව ගරුත්වය රැකීම ප්‍රඥප්තියේ මූලික අරමුණයි."),
        q("න්‍යෂ්ටික ශක්තිය සාමකාමී අරමුණු සඳහා පමණක් භාවිත කිරීම නියාමනය කරන ජාත්‍යන්තර ආයතනය කුමක්ද?", "ජාත්‍යන්තර පරමාණුක බලශක්ති ආයතනය (IAEA)", "ලෝක කාලගුණ සංවිධානය (WMO)", "විශ්ව තැපැල් සංගමය (UPU)", "ජාත්‍යන්තර කම්කරු සංවිධානය (ILO)", "ඔස්ට්‍රියාවේ වියානා නුවර මූලස්ථානය පිහිටි IAEA න්‍යෂ්ටික අවි ව්‍යාප්තිය වැළැක්වීමට ක්‍රියා කරයි."),
        q("ආසියා පැසිෆික් කලාපයේ රටවල දිළිඳුකම පිටුදැකීමට සහ යටිතල පහසුකම් සංවර්ධනයට ණය සපයන කලාපීය බැංකුව කුමක්ද?", "ආසියානු සංවර්ධන බැංකුව (ADB)", "යුරෝපීය මහ බැංකුව", "අප්‍රිකානු සංවර්ධන අරමුදල", "සාර්ක් ආහාර බැංකුව", "පිලිපීනයේ මැනිලා නුවර මූලස්ථානය පිහිටි ADB 1966 දී ආරම්භ කරන ලදී."),
        q("ලොව පුරා හදිසි ආහාර අර්බුද හා ස්වාභාවික විපත් අවස්ථාවලදී ජනතාවට ආහාර ආධාර සපයන නොබෙල් සාම ත්‍යාගලාභී UN ආයතනය කුමක්ද?", "ලෝක ආහාර වැඩසටහන (WFP)", "ලෝක සෞඛ්‍ය සංවිධානය (WHO)", "ජාත්‍යන්තර සමුද්‍ර සංවිධානය (IMO)", "ලෝක වෙළඳ සංවිධානය (WTO)", "2020 වසරේ නොබෙල් සාම ත්‍යාගය හිමි වූ WFP මූලස්ථානය ඉතාලියේ රෝමයේ පිහිටා ඇත."),
        q("රටවල් අතර සංවර්ධන ව්‍යාපෘති, දිළිඳුකම අඩු කිරීම හා තිරසාර සංවර්ධන ඉලක්ක සම්බන්ධීකරණය කරන UN ආයතනය කුමක්ද?", "එක්සත් ජාතීන්ගේ සංවර්ධන වැඩසටහන (UNDP)", "ජාත්‍යන්තර අපරාධ අධිකරණය (ICC)", "ජාත්‍යන්තර පොලීසිය (INTERPOL)", "නේටෝ සංවිධානය (NATO)", "UNDP ආයතනය වාර්ෂිකව මානව සංවර්ධන දර්ශකය (HDI) ද ප්‍රකාශයට පත් කරයි."),
        q("ජාත්‍යන්තර සිවිල් ගුවන් සේවා ආරක්ෂාව හා ගුවන් ගමන් නීති නියාමනය කරන එක්සත් ජාතීන්ගේ විශේෂිත ආයතනය කුමක්ද?", "ජාත්‍යන්තර සිවිල් ගුවන් සේවා සංවිධානය (ICAO)", "විශ්ව තැපැල් සංගමය (UPU)", "ආහාර හා කෘෂිකර්ම සංවිධානය (FAO)", "යුනිසෙෆ් (UNICEF)", "කැනඩාවේ මොන්ට්‍රියල් නුවර ICAO මූලස්ථානය පිහිටා ඇත."),
        q("රටවල් අතර තැපැල් හුවමාරු ක්‍රමවත් කිරීම සඳහා 1874 දී පිහිටුවන ලද ලොව පැරණිතම ජාත්‍යන්තර ආයතනයක් වන්නේ කුමක්ද?", "විශ්ව තැපැල් සංගමය (UPU)", "ජාත්‍යන්තර මූල්‍ය අරමුදල (IMF)", "සාර්ක් සංවිධානය", "ලෝක වෙළඳ සංවිධානය", "ස්විට්සර්ලන්තයේ බර්න් නුවර මූලස්ථානය පිහිටි UPU සංවිධානය UN විශේෂිත ආයතනයකි."),
        q("ගෝලීය විදුලි සංදේශ, රේඩියෝ සංඛ්‍යාත හා චන්ද්‍රිකා කක්ෂ සම්බන්ධීකරණය කරන UN ආයතනය කුමක්ද?", "ජාත්‍යන්තර විදුලි සංදේශ සංගමය (ITU)", "ලෝක ආහාර වැඩසටහන (WFP)", "ජාත්‍යන්තර අධිකරණය (ICJ)", "යුනෙස්කෝ (UNESCO)", "ස්විට්සර්ලන්තයේ ජිනීවා නුවර ITU මූලස්ථානය පිහිටා ඇත."),
        q("දකුණු ආසියානු කලාපීය සහයෝගීතා සංවිධානයේ (SAARC) මූලික අරමුණක් වන්නේ කුමක්ද?", "දකුණු ආසියාතික ජනතාවගේ සුබසාධනය නැංවීම, ආර්ථික වර්ධනය හා සාමූහික ස්වයං විශ්වාසය ශක්තිමත් කිරීම", "කලාපීය හමුදා සන්ධානයක් පිහිටුවීම", "එක් රටක පාලනයට අනෙක් රටවල් යටත් කිරීම", "සියලු දේශසීමා වසා දැමීම", "සාර්ක් ප්‍රඥප්තිය අනුව ද්විපාර්ශ්වික මතභේදාත්මක ගැටලු සාර්ක් සමුළුවලදී සාකච්ඡාවට නොගැනේ."),
        q("සාර්ක් සංවිධානයේ තීරණ ගනු ලබන ප්‍රධාන ක්‍රමවේදය කුමක්ද?", "සියලු සාමාජික රටවල ඒකමතිකත්වයෙන් (Unanimity)", "බහුතර ඡන්දයෙන් පමණක්", "ඉන්දියාවේ හා පාකිස්තානයේ නිෂේධ බලයෙන්", "මහලේකම්වරයාගේ තනි නියෝගයෙන්", "සෑම මට්ටමකදීම සාමාජික රටවල් 8 හිම ඒකමතික එකඟතාව අනුව තීරණ ගැනේ."),
        q("යුරෝපා සංගමයේ (EU) සාමාජික රටවල් අතරින් රටවල් බහුතරයක් භාවිත කරන පොදු ව්‍යවහාර මුදල් ඒකකය කුමක්ද?", "යූරෝ (Euro)", "ස්ටර්ලින් පවුම", "ස්විස් ෆ්‍රෑන්ක්", "ඇමරිකානු ඩොලරය", "ආර්ථික හා මූල්‍ය ඒකාබද්ධතාවයේ ප්‍රතිඵලයක් ලෙස 1999 දී යූරෝ මුදල් ඒකකය හඳුන්වා දෙන ලදී."),
        q("බ්‍රසීලය, රුසියාව, ඉන්දියාව, චීනය සහ දකුණු අප්‍රිකාව මූලික වී බිහි කළ නැගී එන ආර්ථිකයන්ගේ ජාත්‍යන්තර සංවිධානය කුමක්ද?", "බ්‍රික්ස් (BRICS)", "නේටෝ (NATO)", "සීටෝ (SEATO)", "ජී-7 (G7)", "නව සංවර්ධන බැංකුව පිහිටුවීමද ඇතුළුව බහුධ්‍රැවීය ආර්ථික සහයෝගීතාව සඳහා BRICS ක්‍රියා කරයි."),
        q("ජාත්‍යන්තර මානුෂීය නීතියේදී 'සමානුපාතිකත්ව මූලධර්මය' (Principle of Proportionality) මඟින් තහනම් කරන්නේ කුමක්ද?", "අපේක්ෂිත හමුදා වාසියට වඩා අධික හානියක් සිවිල් වැසියන්ට හා දේපළවලට සිදු වන ප්‍රහාර", "තුවාල ලැබූ සෙබළුන්ට බෙහෙත් දීම", "සාම සාකච්ඡා පැවැත්වීම", "වෛද්‍ය ගිලන්රථ භාවිතය", "හමුදා ඉලක්කයකට පහර දීමේදී පවා සිවිල් ජනතාවට වන හානිය අවම කළ යුතුය."),
        q("යුද්ධයකදී 'අනවශ්‍ය වේදනා හෝ පීඩා ගෙන දීම වැළැක්වීමේ මූලධර්මය' අනුව තහනම් කර ඇත්තේ කුමක්ද?", "බිම් බෝම්බ, පොකුරු බෝම්බ හා සුව කළ නොහැකි දරුණු තුවාල සිදු කරන ආයුධ භාවිතය", "රතු කුරුස ගිලන් රථ", "හමුදා නිල ඇඳුම් ඇඳීම", "වෛද්‍ය සැපයුම් ගෙන යාම", "සටන්කරුවෙකු සටනින් ඉවත් කිරීමට ප්‍රමාණවත් බලයට වඩා කෲර හිංසා සිදු කරන අවි තහනම්ය."),
        q("ජාත්‍යන්තර මානුෂීය නීතිය යටතේ 'රැවටීම හෙවත් වංචනික යුද උපක්‍රමය' (Perfidy) යනු කුමක්ද?", "රතු කුරුස ලාංඡනය හෝ සුදු සටන් විරාම කොඩිය වැරදි ලෙස පාවිච්චි කර සතුරාට පහර දීම", "හමුදා රේඩියෝ සංඥා භාවිතය", "යුද සිරකරුවන්ට ආහාර දීම", "තුවාලකරුවන් රෝහල් ගත කිරීම", "ආරක්ෂිත සංකේත අවභාවිත කිරීම ජාත්‍යන්තර මානුෂීය නීතිය බරපතල ලෙස උල්ලංඝනය කිරීමකි."),
        q("යුද ගැටුමකදී පාසල්, රෝහල්, ආගමික ස්ථාන, ජලාශ හා විදුලි බලාගාර ආරක්ෂා කළ යුත්තේ ඇයි?", "සිවිල් ජනතාවගේ පැවැත්මට අත්‍යවශ්‍ය මූලික පහසුකම් හා සිවිල් දේපළ වන බැවිනි", "ඒවා හමුදා අවි ගබඩා වන බැවිනි", "එක්සත් ජාතීන්ගේ බදු ගෙවන බැවිනි", "ජාත්‍යන්තර වෙළඳ ගිවිසුම් නිසාය", "1977 අතිරේක ප්‍රොටෝකෝල මඟින් සිවිල් ජනතාවගේ පැවැත්මට අත්‍යවශ්‍ය වස්තූන්ට පහර දීම තහනම් කර ඇත."),
        q("යුද්ධයකදී සිවිල් වැසියන් පලිහක් ලෙස යොදා ගැනීම (Human Shields) ජාත්‍යන්තර මානුෂීය නීතිය අනුව කෙසේ සැලකේද?", "බරපතල යුද අපරාධයක් හා සම්පූර්ණයෙන්ම තහනම් ක්‍රියාවක් ලෙස", "නීත්‍යානුකූල ආරක්ෂක උපක්‍රමයක් ලෙස", "රාජ්‍යතාන්ත්‍රික වරප්‍රසාදයක් ලෙස", "තානාපති මුක්තියක් ලෙස", "හමුදා ස්ථාන ආරක්ෂා කිරීම සඳහා සිවිල් ජනතාව රඳවා තැබීම සම්පූර්ණයෙන්ම තහනම්ය."),
        q("ජාත්‍යන්තර රතු කුරුස කමිටුවේ (ICRC) මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "ජිනීවා", "ලන්ඩන්", "වොෂින්ටන්", "ටෝකියෝ", "ස්විට්සර්ලන්තයේ ජිනීවා නුවර සිට ICRC ලොව පුරා ගැටුම් කලාපවල මානුෂීය සහන සේවා මෙහෙයවයි."),
        q("ශ්‍රී ලංකා රතු කුරුස සමාජය (Sri Lanka Red Cross Society) රට තුළ ඉටු කරන ප්‍රධාන සේවාවක් කුමක්ද?", "ස්වාභාවික ආපදා සහන, ප්‍රථමාධාර පුහුණුව, රුධිර දායක සේවා හා ප්‍රජා සෞඛ්‍ය වැඩසටහන්", "පළාත් පාලන මැතිවරණ පැවැත්වීම", "විදේශ ගමන් බලපත්‍ර නිකුත් කිරීම", "රේගු බදු අය කිරීම", "සෑම දිස්ත්‍රික්කයකම ශාඛා මඟින් ස්වේච්ඡා මානුෂීය සේවා සපයයි."),
        q("යුද සිරකරුවෙකු සතුරු හමුදාව විසින් අත්අඩංගුවට ගත් පසු ඔහුගෙන් බලහත්කාරයෙන් තොරතුරු ලබා ගැනීමට වධහිංසා පැමිණවීම ගැන තුන්වන ජිනීවා සම්මුතිය පවසන්නේ කුමක්ද?", "වධහිංසා හා අමානුෂික සැලකිලි සම්පූර්ණයෙන්ම තහනම්ය", "තොරතුරු ගැනීමට වධහිංසා කළ හැකිය", "ආහාර හා ජලය අත්හිටුවිය හැකිය", "නීතිමය ආරක්ෂාවක් නොමැත", "යුද සිරකරුවෙකු තම නම, නිලය, උපන් දිනය හා හමුදා අංකය පමණක් පැවසීමට බැඳී සිටී."),
        q("සටන්කරුවන්ගේ තුවාලකරුවන්ට ප්‍රතිකාර කරන සෞඛ්‍ය සේවකයන් සතුරු හමුදාවේ අය වුවද ඔවුන්ට පහර නොදිය යුත්තේ ඇයි?", "මානුෂීය නීතිය යටතේ වෛද්‍ය කාර්ය මණ්ඩලයට විශේෂ ආරක්ෂාවක් හිමි බැවිනි", "ඔවුන් තානාපතිවරුන් වන බැවිනි", "ඔවුන්ට නිෂේධ බලය ඇති බැවිනි", "ඔවුන් එක්සත් ජාතීන්ගේ විනිසුරුවරුන් වන බැවිනි", "තුවාලකරුවන්ගේ ජාතිය නොබලා ප්‍රතිකාර කිරීම වෛද්‍ය ආචාරධර්ම හා ජිනීවා සම්මුති මඟින් ආරක්ෂා කෙරේ."),
        q("ජාත්‍යන්තර මානුෂීය නීතියේ 'මිලිටරි අවශ්‍යතාව' (Military Necessity) සහ 'මානුෂීයත්වය' (Humanity) අතර පැවතිය යුතු සම්බන්ධතාව කුමක්ද?", "සතුරා පරාජය කිරීමේ හමුදා අරමුණ හා මානව ජීවිත ආරක්ෂා කිරීම අතර සමතුලිතතාවක් පවත්වා ගැනීම", "සිවිල් නගර සම්පූර්ණයෙන් විනාශ කිරීම", "සියලුම නීති ඉවත දැමීම", "මානුෂීයත්වය සම්පූර්ණයෙන් නොසලකා හැරීම", "යුද්ධයකදී පවා සිදු කළ හැකි හා නොහැකි දේ පිළිබඳ සීමා මෙම මූලධර්ම දෙකෙන් තීරණය වේ."),
        q("ගැටුමකට සම්බන්ධ රටක් තුළින් පිටතට නොගොස් සටන් නොමැති ආරක්ෂිත කලාපයක රැඳී සිටින අවතැන් වූවන්ට ආහාර හා සෙවණ සැපයීමේ මූලික වගකීම කාටද?", "අදාළ රාජ්‍යයට හා ජාත්‍යන්තර මානුෂීය ආයතනවල සහයෝගයට", "වෙනත් මහාද්වීපයක පළාත් සභාවකට", "ලෝක වෙළඳ සංවිධානයට", "ජාත්‍යන්තර ක්‍රිකට් කවුන්සිලයට", "අභ්‍යන්තරව අවතැන් වූ පුද්ගලයන් රැකබලා ගැනීම රජයේ මූලික වගකීමකි."),
        q("පුද්ගලයන් බලහත්කාරයෙන් අතුරුදන් කිරීම, වර්ග සංහාරය හා සිවිල් වැසියන් සමූල ඝාතනය කිරීම ජාත්‍යන්තර නීතිය යටතේ හඳුන්වන්නේ කුමන අපරාධ ලෙසද?", "මනුෂ්‍යත්වයට එරෙහි අපරාධ හා ජන සංහාර", "සුළු රථවාහන වැරදි", "සිවිල් ගිවිසුම් කඩකිරීම්", "පරිපාලන අක්‍රමිකතා", "මෙවැනි බරපතල ජාත්‍යන්තර අපරාධ සඳහා ජාත්‍යන්තර අපරාධ අධිකරණය වගකිව යුත්තන්ට දඬුවම් පමුණුවයි."),
        q("ජාත්‍යන්තර මානව හිමිකම් නීතිය (IHRL) සහ ජාත්‍යන්තර මානුෂීය නීතිය (IHL) අතර ප්‍රධාන වෙනස කුමක්ද?", "මානව හිමිකම් නීතිය සාම කාලයේ හා සැමවිටම අදාළ වන අතර මානුෂීය නීතිය විශේෂයෙන් සන්නද්ධ ගැටුම්වලදී අදාළ වේ", "මානුෂීය නීතිය වෙළඳ බදු ගැන පමණක් වේ", "මානව හිමිකම් නීතිය යුද අවි ගැන පමණක් වේ", "දෙකම ශ්‍රී ලංකාවේ පළාත් පාලන පනත් වේ", "ගැටුම් කාලවලදී මෙම නීති පද්ධති දෙකම එකිනෙකට අනුපූරකව මිනිස් ජීවිත සුරකියි."),
        q("යුද අපරාධ සිදු කළ රාජ්‍ය නායකයන් හෝ හමුදා අණදෙන්නන් නඩු විභාග කිරීමේදී 'ඉහළ නියෝග පිළිපැදීම' නිදහසට කරුණක් ලෙස පිළිගන්නේද?", "නැත, නීති විරෝධී යුද අපරාධ නියෝග ප්‍රතික්ෂේප කිරීමට හමුදා නිලධාරීන් බැඳී සිටී", "ඔව්, ඕනෑම අපරාධයකින් නිදහස් වේ", "විශ්‍රාම යාමෙන් පසු නඩු පැවරිය නොහැකිය", "සාමාන්‍ය සෙබළුන්ට පමණක් නීතිය අදාළ වේ", "නියුරම්බර්ග් මූලධර්ම හා රෝම ව්‍යවස්ථාව අනුව පුද්ගලික අපරාධ වගකීම අදාළ වේ."),
        q("සන්නද්ධ ගැටුම් පවතින ප්‍රදේශවල වාර්තාකරණයේ යෙදෙන 'මාධ්‍යවේදීන්' ජාත්‍යන්තර මානුෂීය නීතිය යටතේ ආරක්ෂා වන්නේ කුමන කණ්ඩායම යටතේද?", "සිවිල් වැසියන් ලෙසය", "සතුරු සටන්කරුවන් ලෙසය", "තානාපති නියෝජිතයන් ලෙසය", "කුලී හේවායන් ලෙසය", "සටන්වලට සෘජුව සහභාගී නොවන තාක් මාධ්‍යවේදීන්ට සිවිල් වැසියන් සතු ආරක්ෂාව හිමිවේ."),
        q("යුද්ධයකදී සිවිල් හෝ ආගමික හා පරිසර පද්ධතිවලට දිගුකාලීන, පුළුල් හා දරුණු හානි සිදු කරන යුද උපක්‍රම තහනම් කරන්නේ ඇයි?", "ස්වාභාවික පරිසරය හා මතු පරපුරේ පැවැත්ම ආරක්ෂා කිරීමටය", "වැසි වර්ෂාව නැවැත්වීමටය", "වන සතුන් අපනයනය කිරීමටය", "භූමිකම්පා ඇති කිරීමටය", "පරිසරය යුද ආයුධයක් ලෙස භාවිත කිරීම 1977 ENMOD සම්මුතිය හා අතිරේක ප්‍රොටෝකෝල මඟින් තහනම්ය."),
        q("ගෝලීය මට්ටමින් දේශපාලන ආරවුල් විසඳීමට රාජ්‍යයන් දෙකක් 'ජාත්‍යන්තර අධිකරණය' (ICJ) වෙත යොමු වීමේ පූර්ව කොන්දේසිය කුමක්ද?", "ආරවුලට සම්බන්ධ රාජ්‍යයන් දෙකම අධිකරණයේ අධිකරණ බලය පිළිගැනීමට එකඟ වීම", "එක් රටක් පමණක් තනිව යුද ප්‍රකාශ කිරීම", "ආරක්ෂක මණ්ඩලය විසුරුවා හැරීම", "රාජ්‍ය නායකයන් ධුරයෙන් ඉවත් වීම", "ICJ ඉදිරියේ නඩු විභාග කළ හැක්කේ ස්වෛරී රාජ්‍යයන් අතර ආරවුල් පමණක් වන අතර පුද්ගලයන්ට නඩු පැවරිය නොහැකිය."),
        q("එක්සත් ජාතීන්ගේ මහා මණ්ඩලයට හෝ ආරක්ෂක මණ්ඩලයට නීතිමය ගැටලුවක් සම්බන්ධයෙන් ජාත්‍යන්තර අධිකරණයෙන් (ICJ) ලබාගත හැකි මගපෙන්වීම කුමක්ද?", "උපදේශන මතය (Advisory Opinion)", "මරණ දඬුවම", "ආර්ථික සම්බාධක නියෝගය", "පාර්ලිමේන්තු විසුරුවා හැරීම", "රාජ්‍යයන් අතර නඩු තීන්දුවලට අමතරව UN ආයතනවලට නීතිමය උපදේශන මත ලබා දීමට ICJ ක්‍රියා කරයි."),
        q("ගැටුමකින් පසු රටක සාමය ස්ථාවර කරමින් නැවත ගැටුම් ඇතිවීම වැළැක්වීම සඳහා එක්සත් ජාතීන් පිහිටුවා ඇති ආයතනය කුමක්ද?", "සාමය ගොඩනැගීමේ කොමිසම (Peacebuilding Commission)", "භාරකාර මණ්ඩලය", "විශ්ව තැපැල් සංගමය", "ලෝක වෙළඳ සංවිධානය", "ගැටුම් පසු අවධියේදී ප්‍රතිසන්ධානය, ආයතන ගොඩනැගීම හා ආර්ථික පුනරුත්ථාපනය සඳහා මෙය සහය වේ."),
        q("ශ්‍රී ලංකාව 1991 දී අත්සන් කොට ස්ථිර කළ ළමුන්ගේ අයිතිවාසිකම් පිළිබඳ එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය (UNCRC) මඟින් ප්‍රධාන වශයෙන් තහවුරු කරන්නේ කුමක්ද?", "වයස අවුරුදු 18ට අඩු සෑම දරුවෙකුගේම පැවැත්ම, සංවර්ධනය, ආරක්ෂාව හා සහභාගීත්ව අයිතීන්", "වැඩිහිටි විශ්‍රාම වැටුප් ක්‍රමය", "රේගු ආනයන බදු", "තානාපති කාර්යාල නීති", "UNCRC යනු ලොව වැඩිම රටවල් සංඛ්‍යාවක් පිළිගෙන ඇති ජාත්‍යන්තර මානව හිමිකම් සම්මුතියයි."),
        q("කාන්තාවන්ට එරෙහි සියලුම ආකාරයේ වෙනස්කම් කිරීම් තුරන් කිරීම සඳහා එක්සත් ජාතීන් සම්මත කළ ජාත්‍යන්තර සම්මුතිය කුමක්ද?", "සීඩෝ සම්මුතිය (CEDAW)", "සැෆ්ටා ගිවිසුම (SAFTA)", "නේටෝ ගිවිසුම (NATO)", "වියානා තානාපති සම්මුතිය", "1979 දී සම්මත කළ CEDAW සම්මුතිය කාන්තා අයිතිවාසිකම් පිළිබඳ ජාත්‍යන්තර ප්‍රඥප්තිය ලෙස හැඳින්වේ."),
        q("එක්සත් ජාතීන්ගේ සංවිධානය 2015 සිට 2030 දක්වා ලෝකයේ සියලු රටවල් එක්ව ඉටු කර ගැනීමට සම්මත කළ ගෝලීය සංවර්ධන ඉලක්ක මාලාව කුමක්ද?", "තිරසාර සංවර්ධන ඉලක්ක 17 (SDGs)", "පංචශීල ප්‍රතිපත්ති 5", "බැංඩුං මූලධර්ම 10", "ජිනීවා සම්මුති 4", "දිළිඳුකම නැති කිරීම, ගුණාත්මක අධ්‍යාපනය, පිරිසිදු ජලය හා සාමය ඇතුළු ඉලක්ක 17ක් මීට ඇතුළත්ය.")
    )
}

